/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const customEvents = api.context.props.customEvents || [];

    function getPaddedValue(value) {
        return value < 10 ? '0' + value : value;
    }

    function formatDuration(milliSeconds) {    
        let formattedValue = '';

        if (milliSeconds || milliSeconds === 0) {
            let seconds = milliSeconds / 1000;
            const hours = parseInt(seconds / 3600);
            seconds = seconds % 3600;
            const minutes = parseInt(seconds / 60);
            seconds = parseInt(seconds % 60);
            formattedValue = getPaddedValue(hours) + ":" + getPaddedValue(minutes) + ":" + getPaddedValue(seconds);
        }

        return formattedValue;
    }

    return customEvents.filter(action => action.Type && action.Type.toLowerCase() === 'topic')
        .sort((a, b) => a.Time - b.Time)
            .map(action => ({
                name: action.Name,
                type: action.Type,
                time: formatDuration(action.Time || 0),
                properties: action.Properties
            }));
}
